(async() => {
  const results = {};

  // Test 1: Invalid email format
  const email1 = document.querySelector('#email');
  const pass1 = document.querySelector('#password');
  const btn1 = document.querySelector('#loginBtn');

  email1.value = 'invalid-email';
  pass1.value = 'password123';
  email1.dispatchEvent(new Event('input', {bubbles: true}));
  pass1.dispatchEvent(new Event('input', {bubbles: true}));

  // Check validity before clicking
  results.invalidEmail = {
    value: email1.value,
    validity: email1.validity ? {
      typeMismatch: email1.validity.typeMismatch,
      valueMissing: email1.validity.valueMissing
    } : null,
    validationMessage: email1.validationMessage,
    customError: email1.validity ? email1.validity.customError : null
  };

  // Check for error message element
  const errorEl = document.querySelector('#emailError, .error, [id$="Error"]');
  results.invalidEmail.errorElement = errorEl ? {
    exists: true,
    text: errorEl.textContent,
    visible: window.getComputedStyle(errorEl).display !== 'none'
  } : {exists: false};

  // Click login
  btn1.click();
  await new Promise(r => setTimeout(r, 500));

  // Check if still on login form (should fail)
  const loginForm1 = document.querySelector('#loginForm');
  const userInfo1 = document.querySelector('#userInfo');
  results.invalidEmail.afterClick = {
    loginFormVisible: loginForm1 ? loginForm1.style.display !== 'none' : null,
    userInfoVisible: userInfo1 ? userInfo1.style.display !== 'none' : null
  };

  // Test 2: Correct credentials
  const email2 = document.querySelector('#email');
  const pass2 = document.querySelector('#password');
  const btn2 = document.querySelector('#loginBtn');

  email2.value = 'test@example.com';
  pass2.value = 'password123';
  email2.dispatchEvent(new Event('input', {bubbles: true}));
  pass2.dispatchEvent(new Event('input', {bubbles: true}));

  btn2.click();
  await new Promise(r => setTimeout(r, 800));

  const userInfo2 = document.querySelector('#userInfo');
  const loginForm2 = document.querySelector('#loginForm');

  results.correctLogin = {
    loginFormVisible: loginForm2 ? loginForm2.style.display !== 'none' : null,
    userInfoVisible: userInfo2 ? userInfo2.style.display !== 'none' : null
  };

  // Get userInfo bounding box (visible card)
  if (userInfo2 && userInfo2.style.display !== 'none') {
    const rect = userInfo2.getBoundingClientRect();
    results.correctLogin.userInfoRect = {
      x: rect.x,
      y: rect.y,
      width: rect.width,
      height: rect.height,
      right: rect.right,
      bottom: rect.bottom
    };
  }

  // Viewport info
  results.viewport = {
    innerWidth: window.innerWidth,
    innerHeight: window.innerHeight,
    scrollWidth: document.documentElement.scrollWidth
  };

  return results;
})()

