(async() => {
  const results = {};

  // First, logout to restore form
  const logoutBtn = document.querySelector('#logoutBtn');
  if (logoutBtn) {
    logoutBtn.click();
    await new Promise(r => setTimeout(r, 300));
  }

  // Now test wrong password
  const email = document.querySelector('#email');
  const pass = document.querySelector('#password');
  const btn = document.querySelector('#loginBtn');

  email.value = 'test@example.com';
  pass.value = 'wrongpassword';
  email.dispatchEvent(new Event('input', {bubbles: true}));
  pass.dispatchEvent(new Event('input', {bubbles: true}));

  // Click and wait for alert
  btn.click();

  // Wait for potential alert
  await new Promise(r => setTimeout(r, 500));

  // Check state after wrong password
  const loginForm = document.querySelector('#loginForm');
  const userInfo = document.querySelector('#userInfo');

  results.wrongPassword = {
    loginFormVisible: loginForm ? loginForm.style.display !== 'none' : null,
    userInfoVisible: userInfo ? userInfo.style.display !== 'none' : null,
    // Try to check if any alert is present - we'll note this limitation
    alertCheck: 'Browser alert cannot be captured via automation - this test requires manual verification'
  };

  // Check localStorage
  const storage = localStorage.getItem('macbot-e2e-s2-parallel-fc45ecd3b62c');
  results.wrongPassword.localStorage = storage;

  return results;
})()

